import { ProxyChannel, type IChannelServer } from "@knorvia/rpc";
import type { ServiceDescriptor } from "./descriptors.js";

/**
 * ServiceCollection — 服务注册中心
 *
 * 服务端用来注册服务实例，并自动暴露到 ChannelServer。
 */
export class ServiceCollection {
  private readonly _services = new Map<string, unknown>();

  register<T>(descriptor: ServiceDescriptor<T>, instance: T): this {
    this._services.set(descriptor.channelName, instance);
    return this;
  }

  get<T>(descriptor: ServiceDescriptor<T>): T {
    const instance = this._services.get(descriptor.channelName);
    if (!instance) {
      throw new Error(`Service not registered: ${descriptor.channelName}`);
    }
    return instance as T;
  }

  getOptional<T>(descriptor: ServiceDescriptor<T>): T | undefined {
    return this._services.get(descriptor.channelName) as T | undefined;
  }

  /** 将所有已注册的服务自动暴露为 channel */
  exposeOnChannelServer(
    server: IChannelServer,
    overrides: ReadonlyMap<string, unknown> = new Map(),
  ): void {
    for (const [channelName, instance] of this._services) {
      const exposed = overrides.get(channelName) ?? instance;
      server.registerChannel(
        channelName,
        ProxyChannel.fromService(exposed as Record<string, unknown>),
      );
    }
  }
}

import { stat } from "node:fs/promises";
import { Emitter } from "@knorvia/rpc";
import type {
  IPromptAttachmentTransferService,
  PromptAttachmentTransferProgress,
} from "./promptAttachmentTransfer.js";

/** 本地 workspace 保持 localPath 零拷贝，不伪造上传进度。 */
export function createLocalPromptAttachmentTransferService(): IPromptAttachmentTransferService {
  const emitters = new Map<string, Emitter<PromptAttachmentTransferProgress>>();
  const getEmitter = (operationId: string) => {
    const existing = emitters.get(operationId);
    if (existing) return existing;
    const emitter = new Emitter<PromptAttachmentTransferProgress>({
      onDidRemoveLastListener: () => {
        emitters.delete(operationId);
        emitter.dispose();
      },
    });
    emitters.set(operationId, emitter);
    return emitter;
  };

  return {
    async stage(params) {
      const bytes =
        typeof params.sizeBytes === "number" && params.sizeBytes > 0
          ? params.sizeBytes
          : await stat(params.localPath)
              .then((value) => value.size)
              .catch(() => 0);
      return {
        operationId: params.operationId,
        ref: params.localPath,
        bytes,
        staged: false,
      };
    },
    async adopt() {},
    async cancel() {},
    async cleanup() {},
    onDynamicProgress: (operationId) => getEmitter(operationId).event,
  };
}

